window.__BUNDLE__={"generatedAt":"2026-09-14T20:01:24.055114+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-07","archiveCutoff":"2021-09-15","addedToday":225,"addedThisRun":225,"fetchStats":{"hf":232,"arxiv":1241,"total":1473},"freshness":{"latestPaperDate":"2026-09-14","latestPublishedDate":"2026-09-14","latestBatchCount":198,"newInLast24h":225,"newInLast48h":225},"historyTotal":13354,"topicCounts":{"Multi-Agent":2004,"Evaluation":7090,"Planning":1072,"Memory":283,"Code Agent":589,"Interpretability":482,"Agentic RAG":1109,"Agentic Search":1378,"RL for LLM":870,"Reasoning":3910,"Hallucination":777,"Post-Training":1664,"Alignment":1840,"World Model":171,"Tool Use":1108,"Agent Safety":2137,"Computer Use":234,"Reflection":503,"VLM Training":802,"LLM Training":1523,"Fine-tuning":1964,"Multimodal Agent":80,"Agent Framework":704,"Error Attribution":103,"Data Engine":282},"count":36,"recentTotal":1743,"archiveCount":0,"archiveTotal":11611,"sources":{"hf":42,"arxiv":1701,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"source":"hf","title":"SAS: Simple Attention Sparsification via End-to-End Optimization of Context Ranking","announceDate":"2026-09-14","hfUrl":"https://huggingface.co/papers/2609.13141","pdf":"https://arxiv.org/pdf/2609.13141.pdf","tags":["Post-Training","Reasoning","Alignment"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.13141","authors":["Zhiwei Li","Lei Zhu","Hao Gu","Xiang Hu","Yan Wang","Haitao Mi","Sirui Han","Leo Liang","Zhijiang Guo"],"id":"arxiv:2609.13141","arxiv":"https://arxiv.org/abs/2609.13141","date":"2026-09-14","topics":["Post-Training","Reasoning","Alignment"],"upvotes":50,"abstract":"Post-training attention sparsification reduces the quadratic cumulative attention cost of pretrained Transformers by selecting a small set of context units (tokens or blocks) for each query. Existing trainable methods usually use a lightweight selector to score context units, followed by hard Top-K selection that blocks gradients from the language modeling loss. Consequently, these methods commonly distill layer-wise dense attention distributions. Although this encourages the selector to rank context units by dense attention weights in the original model, the ranking is not directly aligned with their impact on predictions under a fixed attention budget (i.e., the number of attended context units per query), potentially wasting the limited budget on less useful units. To address this misalignment, we propose Simple Attention Sparsification (SAS), a gated sparse attention mechanism that o"},{"source":"hf","title":"StepAudio 3 Gen Technical Report","hfUrl":"https://huggingface.co/papers/2609.12945","pdf":"https://arxiv.org/pdf/2609.12945.pdf","tags":["LLM Training","Fine-tuning"],"url":"https://arxiv.org/abs/2609.12945","authors":["Bin Lin","Bo Zhao","Boyang Wang","Boyang Zhang","Boyong Wu","Chao Yan","Chen Geng","Chen Wu","Cheng Yi","Chengli Feng","Chenglin Zhu","DanNi Wan","Daxin Jiang","Dongqing Pang","Fei Tian","Feng Tian","Future Li","Gang Yu","Guanglong Yang","Jia Peng","Jiahao Song","Jiamin Fan","Jiangjie Zhen","Jianzheng Gao","Jun Chen","Li Xie","Lifang Zhang","Lingli Ji","Liying Shi","Lun Cai","Min Xu","Na Wang","Peilin Li","Peng Yang","Pengfei Tan","Qingjian Lin","Ruijie Xiong","Runze Li","Shenghua Hu","Shi Qiu","Siqi Tu","Siyi Zhou","Tianjiao Deng","Wanying Lu","Weiming Niu","Wen Sun","WenWen Qu","Xiangyu Zhang","Xianwei Zhang","XiaoSu Su","Xing Chen","Xinyu Liu","Xuerui Yang","Yang Li","Yang Yang","Yechang Huang","Yibo Zhu","Yifan Zhang","Yiyang Xu","Yu Fu","Yu Luo","Yu Zhou","Yumang Wang","Yunzhou Ju","Yuxiang Yang","Zekai Liu","Zengwei Yao","Zhenwei Mou","Zheqi Dai","Zhiyue Wu","Zichao Zhou"],"id":"arxiv:2609.12945","arxiv":"https://arxiv.org/abs/2609.12945","date":"2026-09-14","topics":["LLM Training","Fine-tuning"],"upvotes":28,"abstract":"We introduce StepAudio 3 Gen, a general-purpose audio generation model that supports zero-shot text-to-speech (TTS), voice design, vocal generation, sound effects, music, vibe speech, and mixtures of multiple audio types within a unified framework. At its core, StepAudio 3 Gen is a discrete autoregressive generator that models audio directly over residual vector quantization (RVQ) tokens, departing from the diffusion Transformer-based continuous generation paradigm prevalent in recent general audio models. Its StepAudio Tokenizer represents general audio at 12.5 Hz in a shared $16 \\times 2048$ residual code space, jointly quantizing semantic and waveform-level acoustic features so that each code layer preserves both types of information. For generation, the backbone predicts the first codebook along the time axis using autoregressive modeling, while a lightweight causal Transformer compl"},{"source":"arxiv","title":"SoK: Rethinking Jailbreaking in the Era of Agentic AI: Attacks, Defenses, and Practical Consideration","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12413.pdf","tags":["Agent Safety","Multi-Agent","Tool Use","Reasoning","Planning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12413","authors":["Md Jueal Mia","Yanzhao Wu","Selcuk Uluagac","M. Hadi Amini"],"id":"arxiv:2609.12413","arxiv":"https://arxiv.org/abs/2609.12413","date":"2026-09-14","topics":["Agent Safety","Multi-Agent","Tool Use","Reasoning","Planning","Evaluation","Alignment"],"upvotes":0,"abstract":"Large language models (LLMs) are rapidly evolving from conversational assistants into agentic AI systems that reason, plan, invoke tools, maintain persistent memory, communicate with other agents, and execute multi-step tasks. At the same time, modern models exhibit substantially stronger native safety alignment than earlier generations on which many jailbreak attacks and defenses were originally studied. This shift raises a fundamental question: \\textit{which established jailbreak-security findings remain valid in the era of modern LLMs and agentic AI?} We address this question through a Systematization of Knowledge (SoK) that reframes jailbreak security around the full agentic execution pipeline. We develop unified taxonomies of attacks and defenses spanning user interaction, planning and reasoning, memory, tool use, and inter-agent communication, and introduce a security--utility--eff"},{"source":"arxiv","title":"Earth-Agent-Pro: Towards Real-World Full-Chain Earth Observation with Agents","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12533.pdf","tags":["Post-Training","LLM Training","Tool Use","Planning","Evaluation"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12533","authors":["Zhutao Lv","Chenhao Dang","Yi Feng","Yanpei Gong","Xiaolei Wang","Junyan Ye","Conghui He","Weijia Li"],"id":"arxiv:2609.12533","arxiv":"https://arxiv.org/abs/2609.12533","date":"2026-09-14","topics":["Post-Training","LLM Training","Tool Use","Planning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Real-world Earth observation (EO) agents must translate high-level scientific questions into executable workflows to acquire observations, prepare data, perform domain computations, and derive conclusions from runtime evidence. Existing EO agents typically start from supplied observations, while benchmarks typically provide prepared inputs or candidate answers, leaving full-chain open-world EO execution largely untested. We present Earth-Agent-Pro, an execution-adaptive Plan-and-Execute framework using expert-authored skills to constrain planning and runtime tool use. Workflow-centered structured memory records planned steps, accepted evidence, and their dependencies, enabling repair of only the affected workflow suffix when runtime evidence invalidates a step. Separate large language model adapters use sequence-level supervised fine-tuning for planner workflow composition and node-level"},{"source":"arxiv","title":"Occamy-1.0: Open Pareto-frontier 35B Intelligence for Co-work","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.11977.pdf","tags":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation"],"submittedDate":"2026-09-04","url":"https://arxiv.org/abs/2609.11977","authors":["Wenhui Chen","Shiwen Cheng","Hao Dong","Chenda Duan","Ruixiang Feng","Zhong Guan","Boqiang Guo","Xueyuan Han","Haojie Hao","Liangmeng Huang","Zhelong Huang","Xinke Kong","Hongyu Li","Jiazheng Li","Junbo Li","Qingchuan Li","Yukun Lian","Chang Liu","Tianyu Liu","Zicheng Liu","Shuyi Ouyang","Yijun Pan","Kunyu Shi","Xiaojun Tang","Bingquan Wang","Kesu Wang","Yuchen Wang","Sibo Wei","Sicong Xie","Xiaoying Xing","Yi Xu","Zhijun Xu","Hongwei Xue","Qingcheng Zeng","Di Zhang","Guannan Zhang","Haochen Zhang","Tianlong Zhang","Tianyu Zhao","Tianyu Zhao","Yanjun Zheng","Jialong Zhu","Zijian Zou"],"id":"arxiv:2609.11977","arxiv":"https://arxiv.org/abs/2609.11977","date":"2026-09-14","topics":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation"],"upvotes":0,"abstract":"Co-work agents execute complex workflows that combine information gathering, tool use, coding, and file manipulation across many model invocations. Because cost and latency accumulate over the full episode, their practical value depends not only on peak capability but also on how efficiently that capability is delivered. Yet many steps in everyday work emphasize state tracking, coordination, recovery, and follow-through rather than frontier-scale reasoning. We present Occamy-1.0, a cost-efficient co-work model obtained by further training the post-trained Qwen3.6-35B-A3B checkpoint. We construct execution-grounded data and environments, capture replayable long-horizon trajectories across multiple harnesses, and use staged post-training to develop and consolidate complementary execution capabilities. Across a broad suite of co-work benchmarks, Occamy-1.0 is consistently among the stronges"},{"source":"arxiv","title":"Online Video Agent Harness for Long Video Understanding","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12818.pdf","tags":["VLM Training","Reasoning","Hallucination","Evaluation","Multimodal Agent"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12818","authors":["Sen Yang","Boqiang Duan","Jing Yang","Weihao Bo","Jie Liu","Boyuan Tong","Ze Feng","Wenkang Zhang","Jingdong Wang","Hua Wu"],"id":"arxiv:2609.12818","arxiv":"https://arxiv.org/abs/2609.12818","date":"2026-09-14","topics":["VLM Training","Reasoning","Hallucination","Evaluation","Multimodal Agent"],"upvotes":0,"abstract":"Long video understanding often behaves like a visual needle-in-a-haystack problem: query-relevant evidence is sparsely distributed across long temporal spans, while packing dense frames into a single VLM context incurs \\textit{context rot} and high cost. Existing video agents often rely on query-agnostic offline preprocessing or ad hoc tool sets, which can miss query-specific details and waste computation. In this work, we present VideoXAgent, a purely online video-agent harness for long video understanding that starts from the given video file and user query, plans and decomposes the task, invokes specialized expert tools on demand, and aggregates multimodal evidence to produce a final answer while resolving conflicts among observations. To support this on-demand invocation, we design a suite of heterogeneous expert tools guided by a data-driven taxonomy of atomic capabilities, spanning"},{"source":"arxiv","title":"AMDKernelVault: Large-Scale Datasets and Agentic Training for AMD GPU Kernel Optimization","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12471.pdf","tags":["LLM Training","Evaluation","Fine-tuning","Reflection","RL for LLM"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12471","authors":["Ji Liu","Saptarshi Majumder","Yiqing Huang","Wenwen Ouyang","Umang Pandey","Zeping Li","Chushi Chen","Zihao An","Puyuan Yang","Zekai Li","Sina Rafati","Ziqiong Liu","Pratik Prabhanjan Brahma","Dong Li","Zicheng Liu","Sharon Zhou","Emad Barsoum"],"id":"arxiv:2609.12471","arxiv":"https://arxiv.org/abs/2609.12471","date":"2026-09-14","topics":["LLM Training","Evaluation","Fine-tuning","Reflection","RL for LLM"],"upvotes":0,"abstract":"We introduce AMDKernelVault, an open HIP and Triton kernel corpus and training framework for recent AMD CDNA GPUs. Existing LLM-based kernel agents are largely CUDA/NVIDIA-centric and often depend on repeated frontier-LLM calls for generation, reflection, and optimization. To address this gap, we develop HIPKernelGen and TritonKernelGen, agent-driven pipelines that transform PyTorch references into HIP or Triton kernels, compile and validate candidates under ROCm, and latency-profile them on AMD hardware. The corpus contains 62,153 execution-verified HIP kernel samples, 2,377 production-grounded ROCm Libraries QA entries, and 39,893 Triton kernels. We further train Qwen3-8B with supervised fine-tuning and execution-aware reinforcement learning as a demonstration of the corpus's utility. Under fixed evaluation budgets, it achieves the highest correctness among the compared models on PyTor"},{"source":"arxiv","title":"CanvasAnneal: Curriculum Reinforcement Learning for Diffusion Language Models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.13060.pdf","tags":["Post-Training","Tool Use","Reasoning","Evaluation","RL for LLM"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.13060","authors":["Blake Olson","Yuhang Song","Emmett McQuinn","Yuan Shangguan"],"id":"arxiv:2609.13060","arxiv":"https://arxiv.org/abs/2609.13060","date":"2026-09-14","topics":["Post-Training","Tool Use","Reasoning","Evaluation","RL for LLM"],"upvotes":0,"abstract":"Diffusion Language Models (DLMs) offer promising parallel generation capabilities but lag behind autoregressive models in complex reasoning and tool-use tasks. While Reinforcement Learning (RL) has recently been applied to enhance DLMs, standard RL approaches suffer from an exploration bottleneck. To address this, we inject reasoning priors from a stronger teacher model to guide RL exploration. In this paper, we introduce CanvasAnneal, a curriculum-guided diffusion RL framework. During the initial RL phase, we warm-start exploration by injecting teacher-generated reasoning traces into the initial diffusion canvas. As training progresses, we gradually remove this guidance and require the model to generate more of the reasoning trajectory independently. Across mathematical reasoning and tool-use benchmarks, CanvasAnneal improves over standard diffu-GRPO on MATH500, Countdown, and Tau2 and "},{"source":"arxiv","title":"Sampling via Decision-Flow: Training-Free Extraction of Improved Latent Reasoning Paths in Large Language Models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12317.pdf","tags":["Post-Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12317","authors":["Zhendong Mi","Shaoyi Huang"],"id":"arxiv:2609.12317","arxiv":"https://arxiv.org/abs/2609.12317","date":"2026-09-14","topics":["Post-Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"upvotes":0,"abstract":"A central question in LLM reasoning is whether reinforcement learning (RL) instills genuinely new capabilities or merely reshapes how existing knowledge is expressed during inference. Building on the distribution-sharpening hypothesis, which holds that RL reallocates probability mass toward high-reward trajectories already latent in base models, we ask: can we unlock those latent paths without costly RL fine-tuning? We present Decision-Flow Sampling (DF-Sample), a training-free, data-free inference-time framework that constructs a hierarchical reasoning tree, scores terminal nodes for quality, and back-propagates utilities to inform each intermediate branching decision. Unlike conventional sampling strategies that make purely local step-wise choices, DF-Sample performs explicit global trajectory evaluation before committing to a path, recovering high-quality but low-probability reasoning"},{"source":"arxiv","title":"Beyond Vector Similarity: Hierarchical Context-Aware Graph RAG vs Standard RAG in Enterprise Code Migration","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12464.pdf","tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12464","authors":["Nilesh Jaiswal","Aniket Agrawal","Arjit Shukla","Divya Malhotra","Saurabh Garg","Suchit Puri","Suddhasatwa Bhaumik"],"id":"arxiv:2609.12464","arxiv":"https://arxiv.org/abs/2609.12464","date":"2026-09-14","topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"upvotes":0,"abstract":"As enterprises modernize legacy monolithic systems to microservices, Large Language Models (LLMs) are heavily utilized for automated code translation. However, traditional vector-based Retrieval-Augmented Generation (Standard RAG) struggles to capture topological relationships. It fetches isolated chunks that sever inheritance chains, leading to high compilation failure rates. This paper introduces a Hierarchical Context-Resident Graph (HCRG) methodology to resolve these limitations. Our pipeline uses tree-sitter for Abstract Syntax Tree (AST) extraction, maps architectural edges into a Google Cloud Spanner Property Graph, and serializes this structure into a Gemini Context Cache for topological, parent-first code translation. We shift evaluation from naive text-overlap to a custom 7-metric Software Engineering framework. Traditional metrics like CodeBLEU (which scored 91% for both metho"},{"source":"arxiv","title":"A Graph-Based Approach for Mapping Kernel-Level Telemetry to MITRE ATT&CK","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12841.pdf","tags":["Agentic RAG","Agentic Search","Agent Safety","Reasoning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12841","authors":["Matteo Lupinacci","Luigi Arena","Francesco Blefari","Angelo Furfaro"],"id":"arxiv:2609.12841","arxiv":"https://arxiv.org/abs/2609.12841","date":"2026-09-14","topics":["Agentic RAG","Agentic Search","Agent Safety","Reasoning"],"upvotes":0,"abstract":"Mapping observed system behavior to standardized frameworks like MITRE ATT&CK is essential for threat-informed defense, but remains largely manual. Existing automated methods depend on Cyber Threat Intelligence reports, which offer only retrospective accounts of attacks. Low-level telemetry, i.e. kernel-level system calls, instead provides evidence of adversary behavior, yet its volume and complexity have limited its use for automated mapping. We present a methodology that collects kernel-level events via eBPF, correlates attacker commands into a provenance graph, and derives compact graph representations suitable for LLM-based reasoning. These representations are mapped to the MITRE ATT&CK framework using both pure LLM prompting and retrieval-augmented generation (RAG) grounded in the ATT&CK knowledge base, producing ranked technique candidates along with supporting rationales. We imple"},{"source":"arxiv","title":"VRL-Bench: Benchmarking agents on computer control tasks under finite trial budgets","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12404.pdf","tags":["Computer Use","Evaluation","Reflection","RL for LLM"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12404","authors":["Yu Bai","Yukai Miao","Dawei Wang","Li Chen","Yanyu Ren","Yuqian Shi","Dan Li","Ying Xiong","Chengqiu Tan","Run Zhou","Li Li"],"id":"arxiv:2609.12404","arxiv":"https://arxiv.org/abs/2609.12404","date":"2026-09-14","topics":["Computer Use","Evaluation","Reflection","RL for LLM"],"upvotes":0,"abstract":"Learning from trial and error is a promising way to improve language agents on complex tasks such as computer control. Reflexion introduced verbal reinforcement learning, which turns failed trials into text that guides later attempts without updating model parameters. We introduce VRL-Bench, a harness for fair evaluation of trial-and-error learning under finite trial budgets. Across three models on MiniWoB and WebShop, we evaluate updates from several prominent verbal-memory methods spanning Reflexion and later work: each improves observed success over memory-free retry in some settings but reduces it in others. Replay experiments show that using reflection can reduce success rates, revealing a trade-off between exploiting experience and continued exploration. We propose VEX$^2$, a verbal exploration--exploitation scheduler that uses a language model to jointly select policies and alloca"},{"source":"arxiv","title":"BlueLM-GUI Technical Report: A Real-Device-Centric Flywheel for Self-Improving Mobile GUI Agents","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12394.pdf","tags":["LLM Training","Computer Use","Evaluation","Fine-tuning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12394","authors":["Tong Ye","Kunyang Han","Guozhi Wang","Longqiang Luo","Zhifeng Ding","Yongxiang Zhang","Xiaolei Shen","Yuxuan Zhang","Zhuping Zhang","Tao Xu","Yue Pan","Yucheng Zhao","Yupei Hu","Yuanjiang Ouyang","Danfeng Shen","Runqi Lin","Hongda Cai","Zhaoxiong Wang","Mengjia Yan","Yingjie Zhong","Chen Zhou","Zeyu Zhang","Xuwen Zhu","Penggang Shi","Mingcheng Luo","Ziyang Wu","Min Jin","Mingfu Shen","Zairong Xu","Fan Zhang","Hao Wang","Liang Liu","Zhulin Xie","Lijun Yao","Xiao Liang","Liangmin Wen","Liqiang Feng","Feilong Wu","Min Hu","Min Chen","Guanjing Xiong","Xiaohu Ruan","Xiaoxin Chen"],"id":"arxiv:2609.12394","arxiv":"https://arxiv.org/abs/2609.12394","date":"2026-09-14","topics":["LLM Training","Computer Use","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Mobile GUI agents are shifting from multi-module frameworks to native models trained end-to-end, yet industrial deployment faces three persistent gaps. Sandbox training produces a distribution mismatch with production environments; expensive real-device failures remain underutilized; and fixed benchmarks saturate, losing the power to guide iteration. We present BlueLM-GUI, a 35B-A3B mobile GUI agent built as a real-device-centric flywheel that closes these gaps through three principles. Every Sample Matters: a dual-track pipeline with Heterogeneous Triple-System Consensus evaluation and an Error Correction \\& Derivation Module salvages every trajectory into usable supervision. Every Rollout Is Real: a three-stage recipe---continual pre-training, supervised fine-tuning, and agentic reinforcement learning on hundreds of real phones---grounds every rollout in real production environments, s"},{"source":"arxiv","title":"Tasks over Application Manuals: Revealing Gaps in Long-Horizon Procedural Reasoning for Language Models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.13005.pdf","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.13005","authors":["Utkarsh Soni","Syed Shariyar Murtaza","Yifan Nie","Sachin Chandrasekhar","Eugene Wen"],"id":"arxiv:2609.13005","arxiv":"https://arxiv.org/abs/2609.13005","date":"2026-09-14","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"upvotes":0,"abstract":"Large language models (LLMs) have achieved strong performance on a wide range of natural language tasks, and recent benchmarks suggest that they are increasingly adept at multi-hop reasoning. However, these benchmarks are typically short-horizon, requiring only a small number of retrieval or inference steps, and provide limited evidence of reliability on real-world tasks that involve following manuals spanning hundreds of pages with complex, interdependent guidelines. In this paper, we introduce Tasks over Application Manuals (TAM), a benchmark for evaluating long-horizon procedural reasoning. We construct TAM by curating real-world tasks from two domains: ICD-10-CM clinical coding (mapping medical conditions to diagnostic codes) and U.S. federal sentencing (computing crime sentencing guideline outcomes, specifically offense levels), with human-validated labels. Each task requires follow"},{"source":"arxiv","title":"Dynin-Robotics: Omnimodal Unified Diffusion Vision-Language-Action Model","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.13053.pdf","tags":["Post-Training","LLM Training","VLM Training","Evaluation"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.13053","authors":["Hoeun Lee","Jaeik Kim","Jusang Oh","Jinhyeok Kim","Geon Choi","Hyeonggeun Kim","Jaeyoung Do"],"id":"arxiv:2609.13053","arxiv":"https://arxiv.org/abs/2609.13053","date":"2026-09-14","topics":["Post-Training","LLM Training","VLM Training","Evaluation"],"upvotes":0,"abstract":"Visual goal and dynamics prediction can provide language-conditioned robot policies with both a target outcome and a representation of action-dependent scene changes. We bring these predictions into action generation and selection through a shared trajectory model. Dynin-Robotics implements this formulation on Dynin-Omni, an omnimodal masked-diffusion backbone, representing language, visual observations, goals, and actions as discrete tokens. By varying conditioning and target spans, the same model learns action prediction, action-conditioned next-observation prediction, terminal goal-state prediction, and trajectory-to-instruction reconstruction. These interfaces support test-time scaling through goal prediction, action-candidate evaluation, and joint refinement of action and future-state predictions. We continually pretrain the model on approximately 1.33 million trajectories from 48 O"},{"source":"arxiv","title":"WinSyn: An Automated Pipeline for Realistic Enterprise Question-Answering Evaluation","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12171.pdf","tags":["Agentic RAG","Agentic Search","Evaluation","Data Engine"],"submittedDate":"2026-09-10","url":"https://arxiv.org/abs/2609.12171","authors":["Amey Varhade","Ananya Sutradhar","Ravishankar Krishnaswamy","Navin Goyal"],"id":"arxiv:2609.12171","arxiv":"https://arxiv.org/abs/2609.12171","date":"2026-09-14","topics":["Agentic RAG","Agentic Search","Evaluation","Data Engine"],"upvotes":0,"abstract":"Enterprise settings provide a challenging environment for question-answering agents, which often rely on Retrieval-Augmented Generation, Deep Research (DR), and related techniques. Much of this challenge comes from the complexity of enterprise data: information is often spread across evolving and potentially conflict- ing emails, chat messages, documents, and other artifacts. Existing benchmarks typically have limited real-world complexity, short-form responses, and unnatural queries, so they often fail to capture the challenges of enterprise settings. In this work, we introduce an automated pipeline for generating synthetic datasets of emails reflecting realistic workplace scenarios, along with long- and short-form questions and gold answers grounded in the data. Our method simulates long-running enterprise projects spanning several months and involving up to 25 interacting employees ac"},{"source":"arxiv","title":"Cognition on Graph: Navigating Massive Knowledge Space via Cognitive Cycles and Bidirectional Graph-Text Synergy","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12791.pdf","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12791","authors":["Gengxian Zhou","Jian Xu","Zichen Tang","Shiming Xiang","Haihong E","Cheng-Lin Liu"],"id":"arxiv:2609.12791","arxiv":"https://arxiv.org/abs/2609.12791","date":"2026-09-14","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"upvotes":0,"abstract":"Retrieval-Augmented Generation (RAG) has empowered Large Language Models (LLMs) to tackle knowledge-intensive tasks. However, navigating global, heterogeneous knowledge bases (large-scale knowledge graphs and text corpora) for complex reasoning remains a challenge. Existing methods typically employ reactive, graph-driven exploration strategies, which blindly follow graph topology without adapting to the question context or evolving exploration progress, and lack deep bidirectional synergy between graph and text. To address these limitations, we propose CoG (Cognition on Graph), a cognitive-inspired, training-free framework for adaptive knowledge exploration. Drawing inspiration from human problem-solving, CoG performs a continuous plan-explore-reflect cycle, where it proactively formulates investigation plans, performs dual-source retrieval, and dynamically reflects on progress to adjust"},{"source":"arxiv","title":"Bridging Vision Foundation Model Priors with CLIP for Spatial-aware Few-shot Anomaly Detection in Medical Images","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12454.pdf","tags":["LLM Training","VLM Training","Evaluation","Alignment"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12454","authors":["Juzheng Miao","Yuchen Yuan","Cheng Chen","Pheng-Ann Heng"],"id":"arxiv:2609.12454","arxiv":"https://arxiv.org/abs/2609.12454","date":"2026-09-14","topics":["LLM Training","VLM Training","Evaluation","Alignment"],"upvotes":0,"abstract":"Vision-Language Models such as CLIP enable effective few-shot medical anomaly detection (AD) via strong image-text semantic alignment. However, their globally contrastive pretraining lacks explicit spatial supervision, limiting precise lesion localization. In contrast, Vision Foundation Models (VFMs) such as DINO learn spatially coherent patch representations via self-distillation and local-to-global consistency, better capturing fine-grained anatomical structures. Leveraging this complementarity, we propose Spatial-FAD, a spatial-aware few-shot medical AD framework that improves lesion localization by combining VFM spatial priors with CLIP semantics. Specifically, we introduce a VFM-enhanced adapter that injects a structural affinity prior derived from DINO into CLIP features. This structure-guided refinement encourages visual embeddings to better adhere to lesion boundaries while maint"},{"source":"arxiv","title":"Retrieval-Augmented Generation for Scientific Code Understanding","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12190.pdf","tags":["Agentic RAG","Agentic Search","Code Agent","Evaluation"],"submittedDate":"2026-09-10","url":"https://arxiv.org/abs/2609.12190","authors":["Aaron Nobile","Andreas Adelmann","Mohsen Sadr"],"id":"arxiv:2609.12190","arxiv":"https://arxiv.org/abs/2609.12190","date":"2026-09-14","topics":["Agentic RAG","Agentic Search","Code Agent","Evaluation"],"upvotes":0,"abstract":"Large language models have become central to modern coding assistants, but state-of-the-art systems such as Claude Code or Codex rely on very large, cloud-hosted models with significant computational cost and data-privacy implications. This work investigates whether a useful, fully local coding agent can be built around small open-source models by shifting the computational burden away from inference. We develop a Retrieval-Augmented Generation (RAG) system for scientific code understanding that strictly separates an expensive offline ingestion stage parsing, structural graph construction, LLM-generated entity explanations, and embedding from a lightweight online answering stage. The system is evaluated on a 100-question benchmark spanning eleven categories over the IPPL scientific codebase written in C++, with answers scored by an independent frontier model as the judge. Across seven an"},{"source":"arxiv","title":"Reinforcement Learning over Patient Trajectories for Clinical Reasoning in EHR Foundation Models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12277.pdf","tags":["Reasoning","Alignment","Fine-tuning","RL for LLM"],"submittedDate":"2026-09-10","url":"https://arxiv.org/abs/2609.12277","authors":["Yuxin Xiao","Sheng Zhang","Chandan Singh","Tristan Naumann","Hoifung Poon","Jianfeng Gao","Xiaodong Liu"],"id":"arxiv:2609.12277","arxiv":"https://arxiv.org/abs/2609.12277","date":"2026-09-14","topics":["Reasoning","Alignment","Fine-tuning","RL for LLM"],"upvotes":0,"abstract":"Electronic health record (EHR) foundation models trained on longitudinal patient trajectories have demonstrated strong performance across diverse clinical prediction tasks. However, their clinical reasoning capabilities remain constrained by next-token prediction on limited and incomplete EHR data. To address this, we propose a reinforcement learning (RL) fine-tuning framework that treats EHR foundation models as generative policies over patient trajectories. We formulate common clinical prediction problems (e.g., hospital readmission) as event-conditioned, time-windowed reasoning tasks. We then design time-aware, rollout-sensitive rewards to account for finite rollout lengths and temporally inconclusive outcomes. We find that RL fine-tuning consistently improves over pre-trained backbones and strong baselines. Notably, it enables smaller models to surpass larger pre-trained models in da"},{"source":"arxiv","title":"R2VC: Modular Fact-Checking with Retrieval, Verification, and Confidence Calibration","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.11955.pdf","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"submittedDate":"2026-08-06","url":"https://arxiv.org/abs/2609.11955","authors":["Dhruv Dixit","Paritosh Pandey"],"id":"arxiv:2609.11955","arxiv":"https://arxiv.org/abs/2609.11955","date":"2026-09-14","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"upvotes":0,"abstract":"Large language models are increasingly used for automated fact checking, but end-to-end prompting often entangles evidence retrieval, reasoning, and uncertainty estimation, making failures difficult to diagnose and confidence difficult to trust. We present R2VC, a modular retrieve, reason, verify, calibrate architecture for evidence-grounded fact checking with citations and abstention. R2VC combines hybrid sparse+dense retrieval over Wikipedia, a supervised fine-tuned and DPO-aligned generator that produces diverse structured verdict candidates, an external NLI cross-encoder for evidence-based candidate selection, and a lightweight sequence-level calibrator for confidence estimation and selective abstention. On FEVER, an 8B backbone with R2VC achieves 13.74% higher accuracy than baseline. Ablation studies show that verifier-based candidate selection and confidence calibration are the lar"},{"source":"arxiv","title":"MemRetriever: Learning to Search, Reflect, and Retrieve from Long-Term Memory","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.11951.pdf","tags":["Agentic RAG","Post-Training","Memory","Reflection"],"submittedDate":"2026-07-29","url":"https://arxiv.org/abs/2609.11951","authors":["Ruiyang Jiang","Chunyu Li","Zhiyu Li"],"id":"arxiv:2609.11951","arxiv":"https://arxiv.org/abs/2609.11951","date":"2026-09-14","topics":["Agentic RAG","Post-Training","Memory","Reflection"],"upvotes":0,"abstract":"Long-term memory enables personalized agents, but its value depends on retrieving the right evidence at the right time. Most memory systems use static top-k retrieval: they issue one query, return a fixed number of memories, and pass them directly to a downstream model. This approach can miss evidence distributed across sessions, introduce irrelevant content, and waste context, especially for multi-hop, temporal, and knowledge-update questions. We present MemRetriever, an agentic retrieval model that treats memory access as a multi-step search process. At each step, MemRetriever reasons over the current evidence and selects parallel search for broad exploration, serial search for targeted completion, or reflection and denoising for filtering and evidence assessment. It stops when the retained evidence is sufficient for downstream answering. We construct ReAct-style search-memory trajecto"},{"source":"arxiv","title":"Distortion of AI Alignment Revisited: RLHF is a Decent Utilitarian Aligner","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12651.pdf","tags":["Post-Training","Alignment","Fine-tuning","RL for LLM"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12651","authors":["Kazusato Oko","Annie Ulichney","Nika Haghtalab","Han Bao"],"id":"arxiv:2609.12651","arxiv":"https://arxiv.org/abs/2609.12651","date":"2026-09-14","topics":["Post-Training","Alignment","Fine-tuning","RL for LLM"],"upvotes":0,"abstract":"While Reinforcement Learning from Human Feedback (RLHF) is the standard paradigm for aligning large language models with human preferences, its effectiveness in pluralistic settings has been called into question. Notably, recent work by Gölz et al. (2025) demonstrated that the \\textit{distortion} -- defined as the multiplicative gap between the average user utility of the RLHF policy and the optimal average utility -- can scale exponentially with the Bradley-Terry temperature parameter $β$ when users have heterogeneous preferences. In this work, we present a fine-grained analysis of the distortion of RLHF with reward clipping and demonstrate that such exponential degradation is not a fundamental property of the algorithm but rather a consequence of distribution mismatch between the distribution generating preference data ($μ$) and the KL reference policy ($π_{\\mathrm{ref}}$). To this end"},{"source":"arxiv","title":"ParaRecover: A Process-Level Benchmark for Error Localization and Recovery in Parallel Tool-Use Agents","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12345.pdf","tags":["Tool Use","Reasoning","Planning","Evaluation"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12345","authors":["Bowen Guan","Zhentao Yin","Yanming Shen"],"id":"arxiv:2609.12345","arxiv":"https://arxiv.org/abs/2609.12345","date":"2026-09-14","topics":["Tool Use","Reasoning","Planning","Evaluation"],"upvotes":0,"abstract":"Existing agent benchmarks mainly evaluate final task success or tool-call correctness, providing limited insight into whether agents can reliably diagnose and recover from intermediate execution failures. This limitation becomes particularly critical in multi-turn parallel tool-use scenarios, where errors may propagate across dependent branches and trigger cascading failures. We introduce ParaRecover, a process-level benchmark for evaluating error localization and recovery in multi-turn parallel tool-use agents. Built upon a fine-grained taxonomy of 14 error types covering planning dependencies, tool selection, and argument matching, the benchmark comprises 10,626 instances spanning two difficulty levels. To enable finegrained, process-oriented evaluation, we further propose the SDE rubric, which measures structural integrity, diagnostic reasoning, and evolutionary strategy during agent "},{"source":"arxiv","title":"ChitraMiti: Benchmarking Visual Grounding and Modality Reliance in Bengali Geometric Reasoning","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12509.pdf","tags":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12509","authors":["Khan Raiyan Ibne Reza","Sanjana Aktar Maria","Sumaiya Tabassum Nimi","Md Adnan Arefeen"],"id":"arxiv:2609.12509","arxiv":"https://arxiv.org/abs/2609.12509","date":"2026-09-14","topics":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Evaluation of vision-language models (VLMs) for multimodal mathematical reasoning remains limited for low-resource languages and for geometry problems that require reading a diagram and a question together. We introduce ChitraMiti-12.8k, a synthetic benchmark of 12,874 Bengali planar geometry problems paired with structured 15-attribute descriptions, and NCTB-500, a complementary set of 500 diagrams manually extracted from Bengali school textbooks. Using a three-phase protocol that separates diagram-only, diagram-plus-description, and description-only inputs, we show across five open-weight and closed-source VLMs that description-only performance is statistically indistinguishable from diagram-plus-description performance, establishing structured descriptions as a sufficient textual proxy for controlled evaluation. Despite this, models remain poor at cross-modal verification, frequently "},{"source":"arxiv","title":"DementiaCare-Bench: A Modality-Validated Video Benchmark","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12929.pdf","tags":["VLM Training","Multi-Agent","Evaluation","Fine-tuning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12929","authors":["Afrouz Sheikholeslami","Yuankai Qi","Xuyun Zhang","Luping Zhou","Amin Beheshti","Quan Z. Sheng","Ming-Hsuan Yang"],"id":"arxiv:2609.12929","arxiv":"https://arxiv.org/abs/2609.12929","date":"2026-09-14","topics":["VLM Training","Multi-Agent","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Dementia affects an estimated 57 million people worldwide, and for most families the hardest part of care is not memory loss but the behavioral and psychological symptoms of dementia (BPSD): agitation, wandering, resistance to care, sundowning. Understanding these symptoms requires more than recognizing the behavior itself; it also requires knowing what happened beforehand. The same behavior may call for a different response depending on its trigger. Video-language models (VLMs) could potentially support caregivers, yet no existing benchmark evaluates this capability. To fill this gap, we present DementiaCare-Bench: 56 professionally produced caregiver training videos segmented into 94 clips across nine BPSD categories, with 2023 questions generated by a multi-agent pipeline that grounds every clinical claim in a verbatim transcript span. Each question is then probed under four visual co"},{"source":"arxiv","title":"Physics-Aware Video Generation via Agentic Planning and Graph-Guided Optimization","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.13006.pdf","tags":["VLM Training","Planning","Hallucination","Evaluation"],"submittedDate":"2026-07-16","url":"https://arxiv.org/abs/2609.13006","authors":["Minh-Loi Nguyen","Xuan-Vu Le","Thanh-Toan Do","Tam V. Nguyen","Minh-Triet Tran","Trung-Nghia Le"],"id":"arxiv:2609.13006","arxiv":"https://arxiv.org/abs/2609.13006","date":"2026-09-14","topics":["VLM Training","Planning","Hallucination","Evaluation"],"upvotes":0,"abstract":"Video diffusion models (VDMs) have demonstrated remarkable capabilities in synthesizing high-fidelity, photorealistic video content. However, they fundamentally lack an intrinsic understanding of physical laws and frequently produce visually appealing but causally illogical sequences characterized by structural hallucinations and physically implausible dynamics. Injecting physical awareness via training-free test-time optimization is a promising alternative, yet existing methods rely on global gradient updates and rigid scheduling heuristics that inadvertently corrupt passive backgrounds and fail to model complex dynamic state changes. To address this, we propose PhysPlan, a novel training-free guidance framework that shifts the paradigm from stochastic visual interpolation to agentic physics simulation. First, a VLM operates as an iterative cognitive simulator, decomposing multimodal in"},{"source":"arxiv","title":"Physics as the label for measuring and correcting materials reasoning in multimodal models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12181.pdf","tags":["VLM Training","Reasoning","Hallucination","Evaluation"],"submittedDate":"2026-09-10","url":"https://arxiv.org/abs/2609.12181","authors":["Hasan Kurban","Rasul Khanbayov","Mustafa Kurban"],"id":"arxiv:2609.12181","arxiv":"https://arxiv.org/abs/2609.12181","date":"2026-09-14","topics":["VLM Training","Reasoning","Hallucination","Evaluation"],"upvotes":0,"abstract":"Vision-language and language models increasingly interpret materials data, yet benchmarks report that they hallucinate invalid properties and violate physical law. Evaluation matches final answers to scarce human labels, while discovery agents verify final proposals or density functional theory (DFT) execution. Neither measures the physical consistency of a model's reasoning chain. Materials data carries its own physics, making a large class of materials reasoning verifiable without annotation. We introduce MatPCR, a label-free benchmark whose programmatic oracles check diffraction geometry through Bragg's law, scale bars, spectral peaks, and Materials Project-grounded checks of near-hull stability, computed band-gap class, and net magnetization. We define the Physical-Consistency Rate over image and structure inputs; introduce Constraint-Grounded Self-Verification, an agentic loop whose"},{"source":"arxiv","title":"Assisted Spatial Cognition Through Vision-Language Models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12747.pdf","tags":["VLM Training","Reasoning","Alignment"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12747","authors":["H. Riaz","J. B. Fernandez","I. Mills","D. Hickey","F. Cleary","M. I. Ali"],"id":"arxiv:2609.12747","arxiv":"https://arxiv.org/abs/2609.12747","date":"2026-09-14","topics":["VLM Training","Reasoning","Alignment"],"upvotes":0,"abstract":"Multimodal AI, powered by Large Language Models (LLMs) and Vision-Language Models (VLMs), is transforming assistive technologies by enabling simultaneous processing of visual and textual data. This advancement holds significant promise for over 43 million visually impaired and neuro-divergent individuals worldwide who face persistent challenges in navigating indoor and outdoor environments due to limited spatial awareness and insufficient environmental cues. Existing navigation aids often lack comprehensive 3D scene understanding, relying on constrained route-based strategies that hinder user autonomy. In this paper, we introduce a novel end-to-end framework that integrates LLMs, VLMs and digital twin technologies to deliver a spatially cognitive navigation support for visually impaired and neuro-divergent users. Our system captures video input via standard mobile phone cameras, and empl"},{"source":"arxiv","title":"Scaling Clinical Judgment to Evaluate Medical AI","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12822.pdf","tags":["Reasoning","Evaluation","Fine-tuning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12822","authors":["Thomas A. Buckley","Zahir Kanjee","Peter G. Brodeur","Byron Crowe","Anthony M. Pettinato","Aashna P. Shah","Adrian D. Haimovich","Liam G. McCoy","Daniel Restrepo","Ethan Goh","Jonathan H. Chen","Laura Zwaan","Katherine E. Goodman","Daniel J. Morgan","Raja-Elie E. Abdulnour","Adam Rodman","Arjun K. Manrai"],"id":"arxiv:2609.12822","arxiv":"https://arxiv.org/abs/2609.12822","date":"2026-09-14","topics":["Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Blinded physician evaluation has been considered by many to be the gold standard for assessing clinical reasoning in large language models (LLMs). This is difficult to scale; thus, prior studies typically rely on small physician panels, often from a single institution or specialty, which both limits the scientific questions investigated and makes it unclear whether findings would be reproduced with a different set of evaluators. To more rigorously and scalably study clinical reasoning in AI models, here we introduce PrecepTron, an LLM fine-tuned for physician-level evaluation of open-ended responses. PrecepTron was trained using low-rank adaptation (LoRA) of a 32-billion-parameter model on a small number of physician examples. We also release GRAND-ROUNDS, a new large-scale physician-annotated benchmark of 9,217 scores by 11 physicians across seven studies. We show that frontier LLMs in "},{"source":"arxiv","title":"From Collaboration to Capability: Internalizing Routed LLM Experts into Compact Reasoners","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12578.pdf","tags":["Reasoning","Evaluation","RL for LLM"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12578","authors":["Frank Nie","Shuyao Wang","Ethan B. Liu"],"id":"arxiv:2609.12578","arxiv":"https://arxiv.org/abs/2609.12578","date":"2026-09-14","topics":["Reasoning","Evaluation","RL for LLM"],"upvotes":0,"abstract":"A compact controller can coordinate stronger experts by selecting whom to consult, formulating requests, and integrating their responses. We study whether learning from both the controller's decisions and the experts' reasoning and code improves its generation after expert removal. We introduce \\textsc{Rivet} for \\emph{collaboration internalization}: expert-augmented reinforcement learning applies a shared outcome signal to controller decisions and returned expert spans, and verified trajectory internalization consolidates complete successful interactions through format-aware supervised training. The deployed controller generates reasoning, code, and interaction structure with local Python execution and no external LLM. Across seven competition-mathematics benchmarks, RIVET-1.7B and RIVET-4B achieve average accuracies of $28.25\\%$ and $44.16\\%$; Stage~II improves RIVET-4B's accuracy afte"},{"source":"arxiv","title":"GLARE: Generative Learning via Adversarial Reward Estimation For Social Dynamics Forecasting","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12165.pdf","tags":["LLM Training","Reasoning","Evaluation"],"submittedDate":"2026-09-10","url":"https://arxiv.org/abs/2609.12165","authors":["Tenghao Huang","Zhaoxuan Tan","Muhao Chen","Jonathan May","Mengting Wan","Longqi Yang","Pei Zhou","Sihao Chen"],"id":"arxiv:2609.12165","arxiv":"https://arxiv.org/abs/2609.12165","date":"2026-09-14","topics":["LLM Training","Reasoning","Evaluation"],"upvotes":0,"abstract":"Meeting continuation requires tracking the agenda, speaker roles, participant intentions, and disagreement across long multi-party discussions. We introduce the Meeting Dynamic Forecasting Benchmark (MDFB), constructed from 2,207 real-world meetings and 24,794 future-facing queries. Given a transcript prefix and an active question, a model generates a plausible multi-turn continuation in one call. We evaluate utility---progress toward the question---and human-likeness---plausible conversational flow and role consistency---without requiring exact reproduction of the observed future. We further present GLARE, an adaptation of adversarial imitation learning to conditional language generation. A discriminator ranks the observed continuation above samples from the current actor, and its score supplies a KL-regularized policy reward; retraining on current-policy negatives allows the reward lan"},{"source":"arxiv","title":"Hierarchical Belief Modeling for Zero-Shot Opponent Adaptation in Partially Observable Multi-Agent Navigation","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12422.pdf","tags":["Multi-Agent","Reasoning","World Model"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12422","authors":["Kowei Shih","Lu Cheng","Zeyu Wang","Yeyun Xu","Kejian Tong"],"id":"arxiv:2609.12422","arxiv":"https://arxiv.org/abs/2609.12422","date":"2026-09-14","topics":["Multi-Agent","Reasoning","World Model"],"upvotes":0,"abstract":"Lux AI Season 3 requires agents to act under partial observability, randomized episode level dynamics, and a best of five match structure that rewards both tactical execution and fast adaptation. We present HORIZON, a hierarchical agent that combines symmetry aware spatial perception, dual memory belief tracking, relic centric graph attention, information gain driven exploration, and an opponent conditioned policy mixture. HORIZON separates short horizon control from cross match meta reasoning, while auxiliary belief and world model objectives stabilize learning. Trained with PPO in a large scale JAX simulator, the resulting agent explicitly infers hidden game parameters and opponent style. Experiments show consistent gains in match win rate, episode win rate, adaptation gain, and league rating over strong recurrent and feed forward baselines."},{"source":"arxiv","title":"GTA: Graph Theory Agent and Benchmark for Algorithmic Graph Reasoning with LLMs","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12265.pdf","tags":["Reasoning","Code Agent","Evaluation"],"submittedDate":"2026-09-10","url":"https://arxiv.org/abs/2609.12265","authors":["Zixiang Xu","Yanbo Wang","Chenxi Wang","Lang Gao","Zirui Song","Yue Huang","Zhaorun Chen","Xiangliang Zhang","Xiuying Chen"],"id":"arxiv:2609.12265","arxiv":"https://arxiv.org/abs/2609.12265","date":"2026-09-14","topics":["Reasoning","Code Agent","Evaluation"],"upvotes":0,"abstract":"Large Language Models (LLMs) are increasingly asked to reason over structured data such as graphs, yet how reliably they can carry out multi-step graph algorithms in language remains unclear. Existing evaluations tend to use simple tasks on small graphs, to score code generation rather than reasoning over the graph itself, or to fix a single input format. We introduce Graph Theory Bench (GT Bench), a benchmark covering 24 classical graph problems in 44 task-structure settings, with over 100,000 examples across four representations: natural language, structured language, adjacency list, and adjacency matrix. Evaluating eight LLMs on GT Bench shows that accuracy is strongly tied to the input representation, that the best representation shifts with graph density, size, and topology as well as with the model, and that this sensitivity persists, attenuated, in the strongest reasoning models. "},{"source":"arxiv","title":"Reproducing and Evaluating the Generalizability of Subliminal Learning in Open-Weight Models","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.12586.pdf","tags":["Reasoning","Alignment","Fine-tuning"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.12586","authors":["Daan van der Weijden","Nathan Brack","Selene Baez Santamaria"],"id":"arxiv:2609.12586","arxiv":"https://arxiv.org/abs/2609.12586","date":"2026-09-14","topics":["Reasoning","Alignment","Fine-tuning"],"upvotes":0,"abstract":"In this reproduction paper we investigate subliminal learning, a consequence of distillation where teacher models transmit behavioral preference traits through semantically unrelated data. The original paper explores two types of traits (animal preferences and misalignment), three data modalities (number sequences, code, and chain of thought), and several model families. We reproduce their experiments and extend the setup along three axes: new preference categories (actors and politicians), a new task (chess move generation), and an additional open-weight model (Ministral8B). We also run a controlled ablation on the numbers task's answer-space size (1-, 2-, and 3-digit sequences). We focus on open-weight models with accessible checkpoints on HuggingFace, since the original paper's GPT-4.x fine-tuning is no longer available. Our reproduction supports the original paper's claims, but our e"},{"source":"arxiv","title":"MAxBench: A Multinomial Concept Recovery Benchmark","announceDate":"2026-09-14","pdf":"https://arxiv.org/pdf/2609.13072.pdf","tags":["Evaluation","Alignment","Interpretability"],"submittedDate":"2026-09-11","url":"https://arxiv.org/abs/2609.13072","authors":["Divya Appapogu","Freya Behrens","Yonatan Belinkov","Aaron Mueller"],"id":"arxiv:2609.13072","arxiv":"https://arxiv.org/abs/2609.13072","date":"2026-09-14","topics":["Evaluation","Alignment","Interpretability"],"upvotes":0,"abstract":"Fine-grained control of language model behaviors (e.g., steering) is among the more actionable outcomes of interpretability research. For binary concepts such as refusal, a single direction in activation space often suffices for steering. However, many concepts are not binary: Animals and Countries contain many subcategories, each with multiple instances. For these concepts, the search space over possible representation geometries is far larger than for binary concepts; it is thus not clear what geometries are most appropriate, nor what methods are most effective at recovering them. In this work, we introduce MAxBench, a geometry-agnostic evaluation framework for multinomial concept representations based on sampling from the recovered concept representation. We use MAxBench to compare 10 localization methods (covering 5 geometry types) across 6 concepts and 4 models. Using this framework"}],"archive":[],"latestPath":"data/latest.json"};
